const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved;try{saved=new Set(JSON.parse(localStorage.getItem('visual-atlas-saved')||'[]'))}catch{saved=new Set()}
let type='all';const cases=window.ATLAS.cases, colors=['#dfe6cf','#dedbd0','#e4d6c7','#cddedb','#dde0e3','#e4ddc1'];
const safeURL=u=>{try{const v=new URL(u);return v.protocol==='https:'?v.href:''}catch{return ''}};
$('#verification').innerHTML='<b>本期：ChatGPT Images 2.6 · 来源索引预览</b>　已定位 '+cases.length+' 条案例线索。X 原帖当前未能直接读取，作品与版本仍待逐条核实；本站不展示未经授权的原图，也不补写缺失的提示词。<a href="https://openai.com/index/introducing-images-2-6/" target="_blank" rel="noopener"> 官方介绍 ↗</a>';
$('#updated').textContent='资料整理于 '+window.ATLAS.updated;
if(window.ATLAS.repository){$('#repo').href=safeURL(window.ATLAS.repository);$('#repo').hidden=false}
for(const v of [...new Set(cases.map(c=>c.model_family||c.model))])$('#model').add(new Option(v,v));
for(const v of [...new Set(cases.map(c=>c.category))])$('#category').add(new Option(v,v));
function render(){let q=$('#search').value.trim().toLowerCase(),m=$('#model').value,cat=$('#category').value;let filtered=cases.filter(c=>(type==='all'||type==='saved'&&saved.has(c.id)||c.type===type)&&(!m||(c.model_family||c.model)===m)&&(!cat||c.category===cat)&&(!$('#promptOnly').checked||c.prompt)&&(!q||JSON.stringify(c).toLowerCase().includes(q)));$('#count').textContent=filtered.length+' 条来源线索 / '+cases.filter(c=>c.publish_ready).length+' 条完成核验';$('#savedCount').textContent=saved.size;$('#empty').hidden=!!filtered.length;$('#grid').innerHTML=filtered.map((c,i)=>`<article class="card"><button class="visual" data-open="${esc(c.id)}" aria-label="查看${esc(c.title)}">${c.image_url&&c.media_authorized?`<img src="${esc(safeURL(c.image_url))}" alt="${esc(c.title)}" loading="lazy"><span class="media-tag">${esc(c.category)}</span>`:`<div class="source-art" style="--bg:${colors[i%colors.length]}"><small>SOURCE INDEX / ${String(i+1).padStart(2,'0')}</small><strong>${esc(c.title)}</strong><footer><span>文字索引 · 不是作品预览</span><span class="arrow">↗</span></footer></div>`}</button><div class="card-meta"><span>${esc(c.author)}</span><span>${c.publish_ready?'已核验':'待核实'}</span></div><button class="detail-link" data-open="${esc(c.id)}"><h3>${esc(c.title)}</h3></button><p>${esc(c.category)} · ${esc(c.model_family||c.model)}</p><div class="card-bottom"><div class="tags"><span>${c.prompt?'附提示词摘录':'提示词待核实'}</span><span>来源索引</span></div><button class="save ${saved.has(c.id)?'active':''}" data-save="${esc(c.id)}" aria-label="${saved.has(c.id)?'取消收藏':'收藏'}${esc(c.title)}" aria-pressed="${saved.has(c.id)}">${saved.has(c.id)?'★':'☆'}</button></div></article>`).join('')}
function show(id){const c=cases.find(x=>x.id===id);if(!c)return;let via=c.attribution.match(/https:\/\/\S+/)?.[0];$('#detailBody').innerHTML=`<div class="eyebrow">${esc(c.category)} / ${c.publish_ready?'VERIFIED':'PENDING VERIFICATION'}</div><h2 class="detail-title">${esc(c.title)}</h2><p>${esc(c.author)} · ${esc(c.model)}</p>${c.image_url&&c.media_authorized?`<img class="thumb-detail" src="${esc(safeURL(c.image_url))}" alt="${esc(c.title)}">`:''}<p>${esc(c.description)}</p><h4>提示词 ${c.prompt?'· 摘录':''}</h4>${c.prompt?`<pre>${esc(c.prompt)}</pre><button class="copy" id="copyPrompt">复制摘录</button><p>${esc(c.prompt_status)}</p>`:`<p>尚未取得可核实的原始提示词。请前往原帖查看；本站没有用推测内容补齐。</p>`}<h4>来源记录</h4><p>${esc(c.attribution)}</p><a target="_blank" rel="noopener" href="${esc(safeURL(c.source_url))}">查看 X 原帖 ↗</a>${via?`<a target="_blank" rel="noopener" href="${esc(safeURL(via))}">查看发现来源 ↗</a>`:''}<h4>素材说明</h4><p>${esc(c.license)}</p><p>核查日期：${esc(c.checked_at)}。本站显示的彩色文字卡片是索引封面，不是模型生成结果。</p>`;$('#detail').showModal();if(c.prompt)$('#copyPrompt').onclick=async()=>{try{await navigator.clipboard.writeText(c.prompt);toast('已复制提示词摘录')}catch{toast('复制失败，请长按选择文字复制')}}}
function toast(t){$('#toast').textContent=t;$('#toast').style.opacity=1;setTimeout(()=>$('#toast').style.opacity=0,2500)}
$('#grid').onclick=e=>{let b=e.target.closest('[data-open]');if(b)show(b.dataset.open);b=e.target.closest('[data-save]');if(b){saved.has(b.dataset.save)?saved.delete(b.dataset.save):saved.add(b.dataset.save);try{localStorage.setItem('visual-atlas-saved',JSON.stringify([...saved]))}catch{toast('浏览器禁止存储，收藏仅在本次浏览有效')}render()}};
$('.types').onclick=e=>{const b=e.target.closest('[data-type]');if(!b)return;type=b.dataset.type;document.querySelectorAll('[data-type]').forEach(x=>x.classList.toggle('selected',x===b));render()};
['#search','#model','#category','#promptOnly'].forEach(s=>$(s).addEventListener('input',render));$('.close').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close()};$('#reset').onclick=()=>{$('#search').value='';$('#model').value='';$('#category').value='';$('#promptOnly').checked=false;type='all';document.querySelectorAll('[data-type]').forEach(x=>x.classList.toggle('selected',x.dataset.type==='all'));render()};render();
